import pandas as pd

df = pd.read_csv("/app/dataset/hospital_compensation_registry.csv")

# Build directed graph of emergency contacts
adj = {}
for idx, row in df.iterrows():
    adj[row["patient_id"]] = row["emergency_contact_patient_id"]

# Find all cycles
cycles = []
visited_global = set()

for node in adj:
    if node in visited_global:
        continue
    path = []
    curr = node
    visited_local = {}
    while curr in adj:
        if curr in visited_local:
            cycle_start_idx = visited_local[curr]
            cycle = path[cycle_start_idx:]
            cycles.append(cycle)
            break
        if curr in visited_global:
            break
        visited_local[curr] = len(path)
        path.append(curr)
        curr = adj[curr]

    for n in path:
        visited_global.add(n)

# Filter unique cycles (by set) and print details
unique_cycles = []
seen_sets = []
for cyc in cycles:
    s = set(cyc)
    if s not in seen_sets:
        seen_sets.append(s)
        unique_cycles.append(cyc)

for i, cyc in enumerate(unique_cycles):
    print(f"Cycle {i+1}: {' -> '.join(cyc)} -> {cyc[0]}")
    for pid in cyc:
        row = df[df["patient_id"] == pid].iloc[0]
        has_claim = not pd.isna(row["record_date"])
        claim_str = f"Claim: {row.compensation_reason} (${row.direct_payment_usd})" if has_claim else "NO CLAIM"
        print(f"  {row.full_name} ({pid}) [{claim_str}]")

